// The Web Analytics query for the last 24 hours. The site tag is the `token` of Cloudflare's
// beacon (public, but account-specific); the import fills it in from SOPS, so it is not in the repository.
const until = $now.toUTC();
const since = until.minus({ hours: 24 });
const window = { datetime_geq: since.toISO(), datetime_leq: until.toISO() };
const query = `query($account: String!, $site: String!, $since: Time!, $until: Time!) {
  viewer { accounts(filter: { accountTag: $account }) {
    totals: rumPageloadEventsAdaptiveGroups(limit: 1,
      filter: { siteTag: $site, datetime_geq: $since, datetime_leq: $until }) { count sum { visits } }
    referrers: rumPageloadEventsAdaptiveGroups(limit: 10, orderBy: [count_DESC],
      filter: { siteTag: $site, datetime_geq: $since, datetime_leq: $until }) { count dimensions { refererHost } }
  } }
}`;
return [{ json: { graphql: { query, variables: {
  account: '76967f5ede1ce50efce34d90b7e94958', site: 'RESOLVE_SALE_DIGEST_SITE_TAG',
  since: window.datetime_geq, until: window.datetime_leq } } } }];

// Builds the email from the three answers. A step that failed is named in the email instead of
// stopping it: a digest that says "unavailable" is better than no digest.
const rowsOf = name => {
  const json = $(name).first().json;
  return Array.isArray(json.data) ? json.data.map(r => ({ ...r, n: Number(r.n) })) : null;
};
const recent = rowsOf('Events, last 24 h');
const sale = rowsOf('Events, whole sale');
const web = $('Web Analytics, last 24 h').first().json;

const sum = (rows, keep) => rows.filter(keep).reduce((total, r) => total + r.n, 0);
const tally = (rows, event, key) => {
  const counts = {};
  rows.filter(r => r.event === event && r[key]).forEach(r => { counts[r[key]] = (counts[r[key]] || 0) + r.n; });
  return Object.entries(counts).sort((a, b) => b[1] - a[1]);
};
const list = pairs => (pairs.length ? pairs.map(([name, n]) => `${name} ${n}`).join(', ') : 'none');

const block = (title, rows) => {
  if (!rows) return `${title}\n  unavailable: the Analytics Engine query failed (see the n8n execution)`;
  return [
    title,
    `  Visits from a tracked link, by source: ${list(tally(rows, 'visit', 'source'))}`,
    `  Text taps: ${sum(rows, r => r.event === 'text_tap')} (by item: ${list(tally(rows, 'text_tap', 'item'))}; by bundle: ${list(tally(rows, 'text_tap', 'bundle'))})`,
    `  Text taps, by source: ${list(tally(rows, 'text_tap', 'source'))}`,
    `  Item views, by item: ${list(tally(rows, 'view_item', 'item').slice(0, 10))}`,
  ].join('\n');
};

// Many views and no text taps: the price is the likely reason (make reprice).
const MIN_VIEWS = 5;
const candidates = () => {
  if (!sale) return 'unavailable';
  const tapped = new Set(tally(sale, 'text_tap', 'item').map(([item]) => item));
  const found = tally(sale, 'view_item', 'item').filter(([item, n]) => n >= MIN_VIEWS && !tapped.has(item));
  return list(found);
};

const groups = (((web.data || {}).viewer || {}).accounts || [])[0];
let site = 'Cloudflare Web Analytics, last 24 h\n  unavailable: the query returned no data (check the site tag and the token, see the runbook)';
if (Array.isArray(web.errors) && web.errors.length) {
  // GraphQL answers 200 with `errors`, sometimes beside partial data: do not print those figures.
  site = 'Cloudflare Web Analytics, last 24 h\n  unavailable: the GraphQL query returned errors (see the n8n execution)';
} else if (groups && Array.isArray(groups.totals) && groups.totals.length) {
  const totals = groups.totals[0];
  const referrers = (groups.referrers || []).map(g => [g.dimensions.refererHost || 'direct', g.count]);
  site = [
    'Cloudflare Web Analytics, last 24 h',
    `  Page views: ${totals.count}, visits: ${(totals.sum || {}).visits}`,
    `  Top referrers: ${list(referrers)}`,
  ].join('\n');
} else if (groups) {
  site = 'Cloudflare Web Analytics, last 24 h\n  no page views recorded';
}

const day = $now.setZone('America/Denver').toFormat('yyyy-LL-dd');
const text = [
  block('LAST 24 HOURS', recent),
  '',
  block('WHOLE SALE, SO FAR', sale),
  '',
  site,
  '',
  `Repricing candidates (at least ${MIN_VIEWS} views, no text taps): ${candidates()}`,
  'Items with many views and zero text taps are repricing candidates: make reprice ID=<item> PRICE=<usd>.',
  'Counts are events, not people: nothing identifies a visitor.',
].join('\n');
return [{ json: { subject: `Moving sale — daily metrics ${day}`, text } }];
